-- Run after approved PR5.16 apply. Exactly ten checks should be true.
select 'three_raster_products_published' check_name, count(*)=3 passed from software_discovery.products where slug in ('gimp','krita','paint-net') and status='published'
union all select 'raster_route_published_approved',count(*)=1 from software_discovery.escape_routes where slug='photoshop-alternatives-without-a-subscription' and status='published' and editorially_approved
union all select 'exact_three_reviewed_members',count(*)=3 and bool_and(p.slug in ('gimp','krita','paint-net')) from software_discovery.escape_route_products m join software_discovery.escape_routes r on r.id=m.escape_route_id join software_discovery.products p on p.id=m.product_id where r.slug='photoshop-alternatives-without-a-subscription'
union all select 'zero_novelty_and_bounded_member_notes',count(*)=3 and bool_and(m.novelty_score=0 and length(trim(m.editorial_note))>0) from software_discovery.escape_route_products m join software_discovery.escape_routes r on r.id=m.escape_route_id where r.slug='photoshop-alternatives-without-a-subscription'
union all select 'three_verified_bounded_photoshop_anchors',count(*)=3 from software_discovery.product_anchors c join software_discovery.products p on p.id=c.product_id join software_discovery.anchors a on a.id=c.anchor_id where p.slug in ('gimp','krita','paint-net') and a.slug='photoshop' and c.relationship_type='alternative' and c.verification_status='verified' and c.relationship_scope='desktop-raster-layers-painting-basic-adjustment' and length(trim(c.scope_description))>0
union all select 'twelve_verified_key_attributes',count(*)=12 from software_discovery.product_attributes c join software_discovery.products p on p.id=c.product_id join software_discovery.attributes a on a.id=c.attribute_id where p.slug in ('gimp','krita','paint-net') and a.slug in ('no-subscription','pricing-model','trade-off-summary','supported-platforms') and c.verification_status='verified' and c.last_verified_at='2026-10-12T00:00:00Z'
union all select 'three_raster_flags_true',count(*)=3 from software_discovery.product_attributes c join software_discovery.products p on p.id=c.product_id join software_discovery.attributes a on a.id=c.attribute_id where p.slug in ('gimp','krita','paint-net') and a.slug='no-subscription' and c.value_boolean
union all select 'three_public_rpc_scoped_projections',bool_and(software_discovery.product_discovery_page(slug)->>'status'='published' and exists(select 1 from jsonb_array_elements(software_discovery.product_discovery_page(slug)->'anchors') a where a->>'slug'='photoshop' and a->>'scope'='desktop-raster-layers-painting-basic-adjustment')) from (values ('gimp'),('krita'),('paint-net')) p(slug)
union all select 'prior_seven_products_and_two_routes_preserved',(select count(*)=7 from software_discovery.products where slug in ('obsidian','things','omnifocus','2do','affine','anytype','appflowy') and status='published') and exists(select 1 from software_discovery.escape_routes where slug='todoist-alternatives-with-a-one-time-purchase' and status='published' and editorially_approved)
and exists(select 1 from software_discovery.escape_routes where slug='offline-notion-alternatives' and status='published' and editorially_approved)
union all select 'anon_private_evidence_boundary',has_function_privilege('anon','software_discovery.product_discovery_page(text)','EXECUTE') and not has_table_privilege('anon','software_discovery.claim_evidence','SELECT');
